const step = async (n) => { if (n === 1) throw new Error("step " + n); return n; };
const log = [];
async function run() {
  try {
    for (const n of [1, 2]) log.push(await step(n));
    return "done";
  } catch (e) {
    log.push(e.message);
    return "failed";
  } finally {
    log.push("cleanup");
  }
}
